links = re.findall(r'\]\((https://github\.com/[^)]+)\)', text)
bad = []
for url in links:
    m = re.match(r'https://github\.com/deepspeedai/DeepSpeed/blob/84679e9d3a2582bffc53a5259d13cfc7278c9772/(.+?#L(\d+)(?:-L(\d+))?)$', url)
