    path = frag.split('#')[0]
    try:
        n = sum(1 for _ in open(path))
    except FileNotFoundError:
        bad.append(('NOFILE', url)); continue
    if hi > n or lo < 1:
        bad.append(('RANGE', url, n))
print(f"total links: {len(links)}")
for b in bad: print(b)
